import{_ as a,o as r,c as t,a8 as o}from"./chunks/framework.BppdKxCY.js";const m=JSON.parse('{"title":"EP.24 Markdown 增量渲染","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.24-markdown-incremental.md","filePath":"comics/EP.24-markdown-incremental.md","lastUpdated":1793421673000}'),i={name:"comics/EP.24-markdown-incremental.md"};function n(l,e,d,s,c,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="ep-24-markdown-增量渲染" tabindex="-1">EP.24 Markdown 增量渲染 <a class="header-anchor" href="#ep-24-markdown-增量渲染" aria-label="Permalink to &quot;EP.24 Markdown 增量渲染&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../21-frontend-ai-interview">21-frontend-ai-interview.md</a>（21.5 Markdown 增量渲染）· 关联：<a href="./../07-security#71-xss-跨站脚本攻击">7.1 XSS 攻防</a>、<code>examples/07-01-xss-defense.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君每收到一个 token 就 <code>marked.parse(全文)</code> 并全量替换 innerHTML，代码块颜色乱跳、图片狂闪，长回答直接卡死。</li><li><strong>第 2 格</strong>：码叔揭秘根因——Markdown 要&quot;看到结尾才能确定开头&quot;：闭合的代码围栏、表格分隔线、括号没到时，当前解析结果随时翻盘。</li><li><strong>第 3 格</strong>：像素酱实证三板斧：解析降频到 80ms + 未闭合围栏临时补齐 + 已闭合块 keyed memo 冻结，最后一块之外不再重算。</li><li><strong>第 4 格</strong>：码叔结案——DOMPurify 必须在所有变换之后、注入之前消毒；超长内容上虚拟列表与 Worker。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-流式-markdown-的特殊矛盾" tabindex="-1">第 1 格 · 流式 Markdown 的特殊矛盾 <a class="header-anchor" href="#第-1-格-·-流式-markdown-的特殊矛盾" aria-label="Permalink to &quot;第 1 格 · 流式 Markdown 的特殊矛盾&quot;">​</a></h3><ul><li>普通渲染：输入完整，解析一次即可；流式渲染：输入持续增长且不完整；</li><li>每 token 全量解析的总成本随长度叠加，长答案接近 O(n²)；</li><li>全量替换 innerHTML 还会丢滚动、重载图片、重启 CSS 动画与 Mermaid。</li></ul><h3 id="第-2-格-·-哪些语法会-翻盘" tabindex="-1">第 2 格 · 哪些语法会&quot;翻盘&quot; <a class="header-anchor" href="#第-2-格-·-哪些语法会-翻盘" aria-label="Permalink to &quot;第 2 格 · 哪些语法会&quot;翻盘&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>语法</th><th>未闭合时的表现</th></tr></thead><tbody><tr><td>围栏代码块</td><td>代码围栏出现奇数个时，后面的正文全被吃进代码块</td></tr><tr><td>表格</td><td>分隔线 <code>---</code> 未到，行内竖线只是普通文本</td></tr><tr><td>链接/图片</td><td><code>[x](url</code> 未闭合，整段无法成链接</td></tr><tr><td>强调/HTML 块</td><td><code>**</code> 与标签未闭合时行内归属变化</td></tr></tbody></table><p>严格的&quot;只解析新增部分&quot;极易出错，工业界主流是：<strong>高频对累积全文做幂等重渲染，但让 DOM 变化最小</strong>。</p><h3 id="第-3-格-·-三板斧与引擎选型" tabindex="-1">第 3 格 · 三板斧与引擎选型 <a class="header-anchor" href="#第-3-格-·-三板斧与引擎选型" aria-label="Permalink to &quot;第 3 格 · 三板斧与引擎选型&quot;">​</a></h3><ol><li><strong>降频</strong>：token 进缓冲，rAF 合批；Markdown 解析每 50~100ms 一次，流结束再做终态解析；</li><li><strong>半成品稳定化</strong>：奇数围栏先补一个闭合围栏再解析，或最后一块降级纯 <code>&lt;pre&gt;</code>，闭合后再升级高亮；</li><li><strong>块级冻结</strong>：按顶层块切分，已闭合块用内容 hash 作 key + memo，重渲染只发生在尾部一块。</li></ol><ul><li>选型：高频小增量用 marked/markdown-it；React 中等体量用 react-markdown；重 AST 变换用 remark 生态；超大文档用 markdown-wasm 或把解析丢 Worker；</li><li>代码高亮：流式中轻量处理，定稿再上 Shiki；结果按内容 hash 缓存；KaTeX/Mermaid 在语法闭合后才渲染。</li></ul><h3 id="第-4-格-·-安全与长文档" tabindex="-1">第 4 格 · 安全与长文档 <a class="header-anchor" href="#第-4-格-·-安全与长文档" aria-label="Permalink to &quot;第 4 格 · 安全与长文档&quot;">​</a></h3><ul><li>模型输出不可信：<code>&lt;img onerror&gt;</code>、<code>javascript:</code> 链接都能借 Markdown 原生 HTML 注入；</li><li>消毒时机：<strong>所有插件/高亮变换之后、写入 DOM 之前</strong>，用 DOMPurify；react-markdown 配 rehype-raw 时必须加 rehype-sanitize；</li><li>链接强制 <code>rel=&quot;noopener noreferrer&quot;</code> 与协议白名单，CSP 兜底；</li><li>两万字 + 几十段代码：Worker 解析 + 块级 keyed diff + 虚拟列表（视口外 content-visibility）+ 图表/图片懒加载。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../21-frontend-ai-interview#_21-7-3-常见误区总清单">《21.7.3 常见误区总清单》</a></p></blockquote><ol><li>每 token 全量 parse + innerHTML：O(n²)、闪烁、丢滚动；</li><li>未闭合代码块不处理：颜色与结构每帧横跳；</li><li>只在解析前消毒或干脆不消毒：插件可二次产出危险节点；</li><li>流式期间就渲染 Mermaid：语法没闭合时疯狂报错；</li><li>长文档全部进 DOM：节点爆炸，必须窗口化。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li><strong>为什么流式 Markdown 不能&quot;只解析新增部分&quot;？</strong>——块语义依赖结尾（围栏、表格、括号、HTML 块），新 chunk 可能让旧内容归属翻盘；主流做法是对累积全文降频幂等重渲染，配合块级冻结让实际 DOM 变更最小。</li><li><strong>代码块高亮闪烁怎么解？</strong>——奇数围栏临时补闭合稳定解析，或尾块先用纯 pre、闭合后升级高亮；已闭合块按 hash key + memo 冻结；Shiki 结果缓存。</li><li><strong>XSS 防护的关键点？</strong>——把模型输出当不可信输入；DOMPurify 消毒放在所有变换之后、注入之前；链接协议白名单与 noopener；代码块转义；CSP 兜底。</li></ol>',20)])])}const u=a(i,[["render",n]]);export{m as __pageData,u as default};
